(lambda _: kAssert(len("#{1+1}") == 6))(None)
(lambda _: kAssert("#{1+1}" == "#" + "{1+1}"))(None)
(lambda _: kAssert("#{`id`}" == "#" + "{`id`}"))(None)
(lambda _: kAssert(len("#@x") == 3))(None)
(lambda _: kAssert("#@x" == "#" + "@x"))(None)
(lambda _: kAssert(len("#@@x") == 4))(None)
(lambda _: kAssert("#@@x" == "#" + "@@x"))(None)
(lambda _: kAssert(len("#$x") == 3))(None)
(lambda _: kAssert("#$x" == "#" + "$x"))(None)
(lambda _: kAssert("a#b" == "a" + "#" + "b"))(None)
